examples.code:
try:
    int('not-a-number')
except ValueError as error:
    print(type(error).__name__)
    print(str(error))

import traceback
try:
    1 / 0
except ZeroDivisionError as error:
    rendered = ''.join(traceback.format_exception(type(error), error, error.__traceback__))
    print('ZeroDivisionError' in rendered)

try:
    raise ValueError('invalid quantity', 0)
except ValueError as error:
    print(error.args)

try:
    try:
        int('x')
    except ValueError as cause:
        raise RuntimeError('conversion failed') from cause
except RuntimeError as error:
    print(type(error.__cause__).__name__)

import traceback
try:
    def fail():
        raise LookupError('missing item')
    fail()
except LookupError as error:
    print(len(traceback.extract_tb(error.__traceback__)) >= 1)
